79	/** Post a reply to a topic (blocked if the topic is locked). */
80	export async function createReply(
81	  _prev: ForumFormState,
82	  formData: FormData,
83	): Promise<ForumFormState> {
84	  const user = await requireUser();
85	
86	  const topicId = String(formData.get("topic_id") ?? "");
87	  const slug = String(formData.get("slug") ?? "");
88	  if (!topicId) return { error: "Missing topic." };
89	
90	  const parsed = replySchema.safeParse({ body: formData.get("body") });
91	  if (!parsed.success) {
92	    return { error: parsed.error.issues[0]?.message ?? "Write a reply." };
93	  }
94	
95	  const supabase = await createClient();
96	
97	  const { data: topic } = await supabase
98	    .from("topics")
99	    .select("is_locked, author_id, title, slug")
100	    .eq("id", topicId)
101	    .maybeSingle<{
102	      is_locked: boolean;
103	      author_id: string | null;
104	      title: string;
105	      slug: string;
106	    }>();
107	  if (topic?.is_locked) {
108	    return { error: "This topic is locked." };
109	  }
110	
111	  const { error } = await supabase
112	    .from("posts")
113	    .insert({ topic_id: topicId, body: parsed.data.body, author_id: user.id });
114	  if (error) return { error: error.message };
115	
116	  await commitForumImages(supabase, parsed.data.body);
117	
118	  // Notify the topic author (not the replier themselves).
119	  if (topic && topic.author_id && topic.author_id !== user.id) {
120	    const replierName = user.displayName ?? user.username ?? "Someone";
121	    const body = parsed.data.body;
122	    after(() =>
123	      notifyForumReply({
124	        topicAuthorId: topic.author_id!,
125	        topicTitle: topic.title,
126	        slug: topic.slug,
127	        replierName,
128	        excerpt: excerpt(body),
129	      }),
130	    );
131	  }
132	
133	  if (slug) revalidatePath(`/discussions/${slug}`);
134	  return { ok: true };
135	}
