137	type ItemTopic = { id: string; slug: string; is_locked: boolean };
138	
139	/**
140	 * The forum topic backing a project/tool discussion, created lazily on the
141	 * first reply. Uses the secret-key client so the topic is system-owned
142	 * (author_id null) — no single user owns or can delete the shared thread. The
143	 * (item_type, item_id) unique index resolves the create race.
144	 */
145	async function ensureItemTopic(
146	  admin: SupabaseClient,
147	  itemType: "project" | "tool",
148	  itemId: string,
149	  title: string,
150	): Promise<ItemTopic> {
151	  const existing = await admin
152	    .from("topics")
153	    .select("id, slug, is_locked")
154	    .eq("item_type", itemType)
155	    .eq("item_id", itemId)
156	    .maybeSingle<ItemTopic>();
157	  if (existing.data) return existing.data;
158	
159	  const base = slugify(title) || itemType;
160	  const slug = `${base}-${Math.random().toString(36).slice(2, 8)}`;
161	  const path = itemType === "project" ? "/projects" : "/tools";
162	  const { data, error } = await admin
163	    .from("topics")
164	    .insert({
165	      slug,
166	      title: title.slice(0, 140),
167	      body: `Discussion for the ${itemType} [${title}](${PUBLIC_SITE_URL}${path}/${itemId}).`,
168	      item_type: itemType,
169	      item_id: itemId,
170	      author_id: null,
171	      category_id: null,
172	    })
173	    .select("id, slug, is_locked")
174	    .single<ItemTopic>();
175	  if (!error && data) return data;
176	
177	  // Lost the create race — the other writer's topic now exists.
178	  const again = await admin
179	    .from("topics")
180	    .select("id, slug, is_locked")
181	    .eq("item_type", itemType)
182	    .eq("item_id", itemId)
183	    .maybeSingle<ItemTopic>();
184	  if (again.data) return again.data;
185	  throw new Error(error?.message ?? "Could not start the discussion.");
186	}
