329	/** Resolve or dismiss a report (admin/moderator only). */
330	export async function resolveReport(formData: FormData): Promise<void> {
331	  const admin = await requireCapability("moderate");
332	  const id = String(formData.get("id") ?? "");
333	  const status = formData.get("status") === "dismissed" ? "dismissed" : "resolved";
334	  if (!id) return;
335	
336	  const supabase = await createClient();
337	
338	  // Capture the reporter before updating so we can close the loop by email.
339	  const { data: report } = await supabase
340	    .from("reports")
341	    .select("reporter_id, target_type")
342	    .eq("id", id)
343	    .maybeSingle<{ reporter_id: string | null; target_type: string }>();
344	
345	  const { error } = await supabase
346	    .from("reports")
347	    .update({
348	      status,
349	      resolved_by: admin.id,
350	      resolved_at: new Date().toISOString(),
351	    })
352	    .eq("id", id);
353	  if (error) throw error;
354	
355	  if (report?.reporter_id) {
356	    const reporterId = report.reporter_id;
357	    const contextLabel = `a ${report.target_type}`;
358	    after(() =>
359	      notifyReportResolved({ reporterId, status, contextLabel }),
360	    );
361	  }
362	
363	  revalidatePath("/admin/reports");
364	}
