import "server-only";

import { createClient } from "@/lib/supabase/server";
import { extractBareUrls } from "@/lib/links/extract";
import type { LinkPreviewKind } from "@/lib/links/constants";

export type LinkPreview = {
  url: string;
  kind: LinkPreviewKind;
  title: string | null;
  description: string | null;
  site_name: string | null;
  author: string | null;
  image_url: string | null;
};

/**
 * Fetch resolved previews for a set of post bodies in ONE query. Extracts the
 * bare URLs from every body, looks up the cache for successfully-resolved rows,
 * and returns a url → preview map. A cache miss (pending/error/absent) simply
 * isn't in the map, so the UI falls back to the plain markdown link.
 */
export async function getLinkPreviewsForBodies(
  bodies: string[],
): Promise<Map<string, LinkPreview>> {
  const urls = new Set<string>();
  for (const body of bodies) {
    for (const url of extractBareUrls(body)) urls.add(url);
  }
  if (urls.size === 0) return new Map();

  const supabase = await createClient();
  const { data, error } = await supabase
    .from("link_previews")
    .select("url, kind, title, description, site_name, author, image_url")
    .in("url", [...urls])
    .eq("status", "ok");
  if (error) return new Map();

  const map = new Map<string, LinkPreview>();
  for (const row of (data ?? []) as LinkPreview[]) map.set(row.url, row);
  return map;
}

import Image from "next/image";
import { extractBareUrls } from "@/lib/links/extract";
import type { LinkPreview } from "@/lib/links/queries";

function hostOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

/** A single unfurled link rendered as a comic-styled card linking out. */
export function LinkPreviewCard({ preview }: { preview: LinkPreview }) {
  const source = preview.site_name ?? hostOf(preview.url);
  return (
    <a
      href={preview.url}
      target="_blank"
      rel="noopener noreferrer nofollow"
      className="focus-comic group block overflow-hidden rounded-[var(--radius-comic)] border-ink bg-surface shadow-comic transition hover:shadow-comic-lg"
    >
      {preview.image_url && (
        <div className="relative aspect-[1.91/1] overflow-hidden border-b-[3px] border-brand-ink bg-brand-ink/5">
          <Image
            src={preview.image_url}
            alt=""
            fill
            sizes="(max-width: 768px) 100vw, 768px"
            className="object-cover transition group-hover:scale-[1.02]"
          />
          {preview.kind === "video" && (
            <span className="absolute inset-0 flex items-center justify-center">
              <span className="flex h-14 w-14 items-center justify-center rounded-full border-[3px] border-brand-ink bg-brand-lime shadow-comic-sm">
                <svg
                  viewBox="0 0 24 24"
                  aria-hidden="true"
                  className="ml-1 h-6 w-6 fill-brand-ink"
                >
                  <path d="M8 5v14l11-7z" />
                </svg>
              </span>
            </span>
          )}
        </div>
      )}
      <div className="p-4">
        <div className="font-mono text-xs uppercase tracking-widest text-muted">
          {source}
        </div>
        <div className="mt-1 line-clamp-2 font-display text-lg leading-tight text-brand-ink group-hover:text-brand-blue">
          {preview.title ?? preview.url}
        </div>
        {preview.description && (
          <p className="mt-1 line-clamp-2 text-sm text-brand-ink/70">
            {preview.description}
          </p>
        )}
        {preview.author && (
          <div className="mt-2 font-mono text-xs uppercase tracking-widest text-muted">
            {preview.author}
          </div>
        )}
      </div>
    </a>
  );
}

/**
 * Render preview cards for the bare URLs in `body` that have a resolved entry in
 * `previews`. URLs still pending/errored just stay as the plain markdown link
 * rendered elsewhere, so nothing shows here for them.
 */
export function LinkPreviews({
  body,
  previews,
}: {
  body: string;
  previews: Map<string, LinkPreview>;
}) {
  const cards = extractBareUrls(body)
    .map((url) => previews.get(url))
    .filter((p): p is LinkPreview => Boolean(p));
  if (cards.length === 0) return null;
  return (
    <div className="mt-4 flex flex-col gap-3">
      {cards.map((preview) => (
        <LinkPreviewCard key={preview.url} preview={preview} />
      ))}
    </div>
  );
}

