import "server-only";

import type { SupabaseClient } from "@supabase/supabase-js";
import { createAdminClient } from "@/lib/supabase/admin";
import { extractBareUrls } from "@/lib/links/extract";
import { resolveMeta, rehostImage } from "@/lib/links/resolve";

const TITLE_MAX = 300;
const DESCRIPTION_MAX = 600;

function clamp(value: string | null, max: number): string | null {
  if (!value) return null;
  const trimmed = value.trim();
  if (!trimmed) return null;
  return trimmed.length > max ? `${trimmed.slice(0, max - 1)}…` : trimmed;
}

/**
 * Resolve metadata for one URL, re-host its image, and write the result onto
 * the existing link_previews row (matched by url). Best-effort: on any failure
 * it records status 'error' rather than throwing, so a caller iterating many
 * URLs never aborts mid-batch. The row MUST already exist.
 */
export async function resolveAndStore(
  admin: SupabaseClient,
  url: string,
): Promise<void> {
  try {
    const meta = await resolveMeta(url);
    if (!meta) {
      await admin
        .from("link_previews")
        .update({
          status: "error",
          error: "No preview metadata",
          fetched_at: new Date().toISOString(),
        })
        .eq("url", url);
      return;
    }

    const image = meta.imageSourceUrl
      ? await rehostImage(admin, meta.imageSourceUrl, url)
      : null;

    await admin
      .from("link_previews")
      .update({
        status: "ok",
        kind: meta.kind,
        provider: meta.provider,
        title: clamp(meta.title, TITLE_MAX),
        description: clamp(meta.description, DESCRIPTION_MAX),
        site_name: clamp(meta.siteName, 120),
        author: clamp(meta.author, 120),
        image_url: image?.imageUrl ?? null,
        image_path: image?.imagePath ?? null,
        error: null,
        fetched_at: new Date().toISOString(),
      })
      .eq("url", url);
  } catch (err) {
    console.error("[unfurl] failed for", url, err);
    await admin
      .from("link_previews")
      .update({
        status: "error",
        error: err instanceof Error ? err.message.slice(0, 300) : "Unfurl failed",
        fetched_at: new Date().toISOString(),
      })
      .eq("url", url);
  }
}

/**
 * Resolve link previews for every bare URL in a freshly-posted body. Designed
 * to run in the background via next/after — best-effort and NEVER throws.
 * Claims each URL by inserting a pending row (a unique-violation means it's
 * already cached or being resolved elsewhere, so we skip the refetch), then
 * resolves it. Uses the service-key client because link_previews has no
 * member-write RLS policy (members can't forge preview rows).
 */
export async function unfurlPost(body: string): Promise<void> {
  const urls = extractBareUrls(body);
  if (urls.length === 0) return;

  const admin = createAdminClient();
  for (const url of urls) {
    const { data, error } = await admin
      .from("link_previews")
      .insert({ url, status: "pending" })
      .select("id")
      .maybeSingle();
    if (error || !data) continue; // 23505 conflict or claim failed → skip
    await resolveAndStore(admin, url);
  }
}

import { createAdminClient } from "@/lib/supabase/admin";
import type { SupabaseClient } from "@supabase/supabase-js";
import { LINK_PREVIEW_BUCKET } from "@/lib/links/constants";
import { resolveAndStore } from "@/lib/links/unfurl";

/**
 * Maintenance for link previews. Two jobs:
 *
 *  1. Refresh — re-resolve the oldest successfully-cached previews so titles,
 *     images, and (importantly) dead links don't rot, and retry failed ones in
 *     case the source was briefly down. Bounded per run to stay well under the
 *     function timeout; the backlog drains over successive runs.
 *  2. Reclaim — delete re-hosted images no live preview row references. These
 *     arise when a refresh resolves a URL that no longer has an image (the
 *     object path is deterministic per URL, so a refresh that still has an
 *     image overwrites in place and never orphans).
 *
 * Invoked by Vercel Cron (see vercel.json). Auth mirrors the forum image sweep:
 * Vercel sends CRON_SECRET as a bearer token; anything else is rejected.
 */
const REFRESH_OK_AFTER_DAYS = 30;
const REFRESH_ERROR_AFTER_DAYS = 7;
const REFRESH_BATCH = 25;
const RECLAIM_GRACE_MS = 60 * 60 * 1000; // 1h — don't race a fresh upload.
const PAGE = 100;

/** Every image_path still referenced by a live preview row. */
async function referencedPaths(supabase: SupabaseClient): Promise<Set<string>> {
  const refs = new Set<string>();
  for (let from = 0; ; from += PAGE) {
    const { data, error } = await supabase
      .from("link_previews")
      .select("image_path")
      .not("image_path", "is", null)
      .range(from, from + PAGE - 1);
    if (error) throw new Error(error.message);
    const rows = (data ?? []) as { image_path: string }[];
    for (const row of rows) refs.add(row.image_path);
    if (rows.length < PAGE) break;
  }
  return refs;
}

export async function GET(request: Request) {
  const secret = process.env.CRON_SECRET;
  if (secret) {
    const auth = request.headers.get("authorization");
    if (auth !== `Bearer ${secret}`) {
      return Response.json({ error: "unauthorized" }, { status: 401 });
    }
  }

  const supabase = createAdminClient();
  const now = Date.now();
  const okCutoff = new Date(now - REFRESH_OK_AFTER_DAYS * 86400_000).toISOString();
  const errCutoff = new Date(now - REFRESH_ERROR_AFTER_DAYS * 86400_000).toISOString();

  // Phase 1 — refresh the stalest previews (ok past 30d, errored past 7d).
  const { data: stale, error: staleError } = await supabase
    .from("link_previews")
    .select("url, status, fetched_at")
    .or(
      `and(status.eq.ok,fetched_at.lt.${okCutoff}),and(status.eq.error,fetched_at.lt.${errCutoff})`,
    )
    .order("fetched_at", { ascending: true, nullsFirst: true })
    .limit(REFRESH_BATCH);
  if (staleError) {
    return Response.json({ error: staleError.message }, { status: 500 });
  }
  const toRefresh = (stale ?? []) as { url: string }[];
  for (const row of toRefresh) {
    await resolveAndStore(supabase, row.url);
  }

  // Phase 2 — reclaim orphaned re-hosted images.
  const referenced = await referencedPaths(supabase);
  const orphans: string[] = [];
  for (let offset = 0; ; offset += PAGE) {
    const { data, error } = await supabase.storage
      .from(LINK_PREVIEW_BUCKET)
      .list("", { limit: PAGE, offset });
    if (error) {
      return Response.json({ error: error.message }, { status: 500 });
    }
    const objects = data ?? [];
    for (const obj of objects) {
      if (referenced.has(obj.name)) continue;
      // Grace window: skip objects uploaded very recently (race with an
      // in-flight resolve that hasn't written its image_path yet).
      const stamp = obj.updated_at ?? obj.created_at;
      if (stamp && now - new Date(stamp).getTime() < RECLAIM_GRACE_MS) continue;
      orphans.push(obj.name);
    }
    if (objects.length < PAGE) break;
  }
  if (orphans.length > 0) {
    await supabase.storage.from(LINK_PREVIEW_BUCKET).remove(orphans);
  }

  return Response.json({
    refreshed: toRefresh.length,
    reclaimed: orphans.length,
  });
}

